class METInventItemPriceActivationJob extends RunBaseBatch implements BatchRetryable
{
    FromDate                      fromDate;
    ItemId                        itemId;

    DialogField                   dlgFromDate;
    DialogField                   dlgItemId;

    QueryRun       queryRun;

    BatchHeader    currentBatchHeader;
    int            priceRecordsCount;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        fromDate,
        itemId
    #endmacro
    #define.RetryNum(3)

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();
    ;
    dlgFromDate = dialog.addFieldValue(extendedTypeStr(FromDate), fromDate, "@SYS5209", "@SYS5209");
    dlgItemId   = dialog.addFieldValue(extendedTypeStr(ItemId), itemId);

    return dialog;
}

public boolean getFromDialog()
{
    ;
    fromDate = dlgFromDate.value();
    itemId   = dlgItemId.value();

    SysQuery::findOrCreateRange(
        queryRun.query().dataSourceTable(tableNum(GUPItemBasePrice)),
        fieldNum(GUPItemBasePrice, FromDate))
        .value(fromDate ? queryValue(fromDate) : SysQuery::range(dateNull(), METGlobal::systemDateGet()));

    SysQuery::findOrCreateRange(
        queryRun.query().dataSourceTable(tableNum(GUPItemBasePrice)),
        fieldNum(GUPItemBasePrice, ItemId))
        .value(itemId ? queryValue(itemId) : SysQuery::valueUnlimited());

    return super();
}

public void initParmDefault()
{
    this.initQuery();
    super();
}

public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tablenum(GUPItemBasePrice));
    QueryBuildRange         priceTypeRange, priceActivationStatusRange;
    ;

    priceTypeRange = SysQuery::findOrCreateRange(qbds, fieldnum(GUPItemBasePrice, PriceType));
    priceTypeRange.status(RangeStatus::Locked);
    priceTypeRange.value(queryValue(GUPBasePriceType::BasePriceInventoryCost));

    priceActivationStatusRange = SysQuery::findOrCreateRange(qbds, fieldNum(GUPItemBasePrice, METItemPriceActivationStatus));
    priceActivationStatusRange.value(strFmt('%1', queryValue(METItemPriceActivationStatus::None)));

    SysQuery::findOrCreateRange(qbds, fieldnum(GUPItemBasePrice, ItemId));

    qbds.addSortField(fieldnum(GUPItemBasePrice, ItemId));
    qbds.addSortField(fieldnum(GUPItemBasePrice, InventDimId));
    qbds.addSortField(fieldnum(GUPItemBasePrice, FromDate), SortOrder::Descending);
    qbds.addSortField(fieldnum(GUPItemBasePrice, RecId), SortOrder::Descending);

    queryRun = new QueryRun(query);
}

public container pack()
{
    return [#CurrentVersion, #CurrentList, queryRun.pack()];
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    container  queryCon;
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }
    return true;
}

public QueryRun queryRun()
{
    return queryRun;
}

public void runBatch()
{
    GUPItemBasePrice                        itemBasePrice;
    str                                     batchItemDimKey;
    Set                                     batchProcessedItemDimSet = new Set(Types::String);

    ttsbegin;

    this.initCurrentBatchHeader();

    // Build tasks — no sim creation here, all deferred to sub-tasks
    METInventItemPriceActivationByGUPTasksBuilder tasksBuilder = METInventItemPriceActivationByGUPTasksBuilder::construct()
                  .setBundleSize(InventParameters::find()
                        .InventItemPriceActivationBundleSize);

    // Deduplicate by ItemId+InventDimId before distributing to bundle tasks.
    // Query is sorted ItemId ASC, InventDimId ASC, FromDate DESC — first record per key is the latest.
    // Duplicates are marked Skipped here so each task receives at most one record per key.
    while (queryRun.next())
    {
        itemBasePrice = queryRun.get(tableNum(GUPItemBasePrice));
        batchItemDimKey = strFmt('%1|%2', itemBasePrice.ItemId, itemBasePrice.InventDimId);

        if (batchProcessedItemDimSet.in(batchItemDimKey))
        {
            GUPItemBasePrice basePriceSkip = GUPItemBasePrice::findRecId(itemBasePrice.RecId, true);
            basePriceSkip.metUpdateActivationStatus(METItemPriceActivationStatus::Skipped);
        }
        else
        {
            batchProcessedItemDimSet.add(batchItemDimKey);
            tasksBuilder.addGUPItemBasePrice(itemBasePrice);
            priceRecordsCount++;
        }
    }

    if (priceRecordsCount > 0)
    {
        this.scheduleItemPriceActivationTasks(tasksBuilder.getResult(), priceRecordsCount);
    }

    ttscommit;
}

public void runSequential()
{
    GUPItemBasePrice                        itemBasePrice;
    GUPItemBasePrice                        itemBasePriceUpdate;
    boolean                                 activated;
    Set                                     processedItemDimSet = new Set(Types::String);
    str                                     itemDimKey;

    while (queryRun.next())
    {
        itemBasePrice = queryRun.get(tableNum(GUPItemBasePrice));

        itemDimKey = strFmt('%1|%2', itemBasePrice.ItemId, itemBasePrice.InventDimId);

        boolean alreadyProcessed = processedItemDimSet.in(itemDimKey);

        try
        {
            ttsbegin;

            itemBasePriceUpdate = GUPItemBasePrice::findRecId(itemBasePrice.RecId, true);

            if (alreadyProcessed)
            {
                itemBasePriceUpdate.metUpdateActivationStatus(METItemPriceActivationStatus::Skipped);
            }
            else
            {
                activated = itemBasePriceUpdate.inventItemPriceCreation();

                if (activated)
                {
                    priceRecordsCount++;
                }
            }

            ttscommit;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() <= #RetryNum)
                {
                    retry;
                }
                else
                {
                    this.markFailed(itemBasePrice.RecId);
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() <= #RetryNum)
                {
                    retry;
                }
                else
                {
                    this.markFailed(itemBasePrice.RecId);
                }
            }
            else
            {
                throw Exception::Deadlock;
            }
        }
        catch (Exception::Error)
        {
            this.markFailed(itemBasePrice.RecId);
        }
        catch
        {
            this.markFailed(itemBasePrice.RecId);
        }

        if (!alreadyProcessed)
        {
            processedItemDimSet.add(itemDimKey);
        }
    }
}

public void run()
{
    METProcMetrics procMetrics   = METProcMetrics::construct(METBatchLogOperation::BasePriceActivation_ActivateFuturePrice);
    GUPParameters  gupParameters = GUPParameters::find();

    // For scheduled batch the query is unpacked from a previous run; refresh the date range to today
    if (!fromDate)
    {
        SysQuery::findOrCreateRange(
            queryRun.query().dataSourceTable(tableNum(GUPItemBasePrice)),
            fieldNum(GUPItemBasePrice, FromDate))
            .value(SysQuery::range(dateNull(), METGlobal::systemdateget()));
    }

    // Include open-ended records (ToDate == dateNull) OR records not yet expired (ToDate >= today).
    QueryBuildDataSource qbds = queryRun.query().dataSourceTable(tableNum(GUPItemBasePrice));
    SysQuery::findOrCreateRange(qbds, fieldNum(GUPItemBasePrice, ToDate))
        .value(strFmt('(%1 == %2) || (%1 >= %3)',
            fieldStr(GUPItemBasePrice, ToDate),
            date2StrXpp(dateNull()),
            date2StrXpp(METGlobal::systemdateget())));

    procMetrics.setTotalCountFromQuery(queryRun);
    procMetrics.beginTrace(METInventItemPriceActivationJob::description());

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        if (this.isInBatch())
        {
            this.runBatch();
        }
        else
        {
            this.runSequential();
        }

        if (gupParameters.METCostingVersionId)
        {
            CostingVersion::updateLastActivation(gupParameters.METCostingVersionId);
            CostingVersion::updateLastUpdated(gupParameters.METCostingVersionId);
        }

        procMetrics.endTrace();
    }

    info(strfmt(" %1 record(s) processed", priceRecordsCount));
}

private void initCurrentBatchHeader()
{
    if (this.isInBatch())
    {
        currentBatchHeader = BatchHeader::construct(this.parmCurrentBatch().BatchJobId);
    }
}

private void scheduleItemPriceActivationTasks(Enumerator _taskEnumerator, int _scheduled)
{
    ttsbegin;

    while (_taskEnumerator.moveNext())
    {
        METInventItemPriceActivationByGUPTask bundleTask = _taskEnumerator.current();
        bundleTask.batchInfo().parmRuntimeTask(true);
        bundleTask.batchInfo().parmGroupId(currentBatch.GroupId);
        currentBatchHeader.addTask(bundleTask);
    }

    currentBatchHeader.save();
    ttscommit;
}

private void markFailed(RecId _basePriceRecId)
{
    UserConnection      userCon = new UserConnection();
    GUPItemBasePrice    basePriceForFail;
    basePriceForFail.setConnection(userCon);

    userCon.ttsbegin();

    select firstonly forupdate basePriceForFail
      where basePriceForFail.RecId == _basePriceRecId;

    if (basePriceForFail.RecId)
    {
        basePriceForFail.METItemPriceActivationStatus = METItemPriceActivationStatus::Failed;
        basePriceForFail.doUpdate();
    }

    userCon.ttscommit();
    userCon.finalize();
}

public boolean showQueryValues()
{
    return true;
}

public boolean runsImpersonated()
{
    return true;
}

public boolean canRunInNewSession()
{
    return false;
}

public boolean canGoBatch()
{
    return true;
}

public boolean isRetryable()
{
    return true;
}

public static METInventItemPriceActivationJob construct()
{
    return new METInventItemPriceActivationJob();
}

static ClassDescription description()
{
    return "Metcash - activate cost price";
}

public static void main(Args _args)
{
    METInventItemPriceActivationJob    runObject = METInventItemPriceActivationJob::construct();
    ;
    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
